assign next_quotientC = is_greater_equalC ? op_a_shift_qVotedC|one_shiftC : op_a_shift_qVotedC;
assign div_change_signA =  (sign_aA^sign_bA) &~div_by_zero_qVotedA;
assign div_change_signB =  (sign_aB^sign_bB) &~div_by_zero_qVotedB;
assign div_change_signC =  (sign_aC^sign_bC) &~div_by_zero_qVotedC;
assign rem_change_signA = sign_aA;
assign rem_change_signB = sign_aB;
assign rem_change_signC = sign_aC;

always_comb
  begin
    multdiv_count_dA = multdiv_count_qVotedA;
    accum_window_dA = accum_window_qA;
    op_b_shift_dA = op_b_shift_qVotedA;
    op_a_shift_dA = op_a_shift_qVotedA;
    op_numerator_dA = op_numerator_qA;
    md_state_dA = md_state_qVotedA;
    multdiv_holdA = 1'b0;
    div_by_zero_dA = div_by_zero_qVotedA;
    if (mult_sel_iA||div_sel_iA)
      begin
        unique case (md_state_qVotedA)
          MD_IDLE : 
            begin
              unique case (operator_iA)
                MD_OP_MULL : 
                  begin
                    op_a_shift_dA = op_a_extA<<1;
                    accum_window_dA = {~ (op_a_extA[32]&op_b_iA[0]) , op_a_extA[31:0]&{ 32 {op_b_iA[0]} } };
                    op_b_shift_dA = op_b_extA>>1;
                    md_state_dA = ((op_b_extA>>1)==0) ? MD_LAST : MD_COMP;
                  end
                MD_OP_MULH : 
                  begin
                    op_a_shift_dA = op_a_extA;
                    accum_window_dA = {1'b1, ~ (op_a_extA[32]&op_b_iA[0]) , op_a_extA[31:1]&{ 31 {op_b_iA[0]} } };
                    op_b_shift_dA = op_b_extA>>1;
                    md_state_dA = MD_COMP;
                  end
                MD_OP_DIV : 
                  begin
                    accum_window_dA = {33{1'b1}};
                    md_state_dA = equal_to_zero_iA ? MD_FINISH : MD_ABS_A;
                    div_by_zero_dA = equal_to_zero_iA;
                  end
                MD_OP_REM : 
                  begin
                    accum_window_dA = op_a_extA;
                    md_state_dA = equal_to_zero_iA ? MD_FINISH : MD_ABS_A;
                  end
                default : ;
              endcase
              multdiv_count_dA = 5'd31;
            end
          MD_ABS_A : 
            begin
              op_a_shift_dA = '0;
              op_numerator_dA = sign_aA ? alu_adder_iA : op_a_iA;
              md_state_dA = MD_ABS_B;
            end
          MD_ABS_B : 
            begin
              accum_window_dA = {32'h0, op_numerator_qA[31]};
              op_b_shift_dA = sign_bA ? {1'b0, alu_adder_iA} : {1'b0, op_b_iA};
              md_state_dA = MD_COMP;
            end
          MD_COMP : 
            begin
              multdiv_count_dA = multdiv_count_qVotedA - 5'h1;
              unique case (operator_iA)
                MD_OP_MULL : 
                  begin
                    accum_window_dA = res_adder_lA;
                    op_a_shift_dA = op_a_shift_qVotedA<<1;
                    op_b_shift_dA = op_b_shift_qVotedA>>1;
                    md_state_dA = ((op_b_shift_dA==0)||(multdiv_count_qVotedA==5'd1)) ? MD_LAST : MD_COMP;
                  end
                MD_OP_MULH : 
                  begin
                    accum_window_dA = res_adder_hA;
                    op_a_shift_dA = op_a_shift_qVotedA;
                    op_b_shift_dA = op_b_shift_qVotedA>>1;
                    md_state_dA = (multdiv_count_qVotedA==5'd1) ? MD_LAST : MD_COMP;
                  end
                MD_OP_DIV, MD_OP_REM : 
                  begin
                    accum_window_dA = {next_remainderA[31:0], op_numerator_qA[multdiv_count_dA]};
                    op_a_shift_dA = next_quotientA;
                    md_state_dA = (multdiv_count_qVotedA==5'd1) ? MD_LAST : MD_COMP;
                  end
                default : ;
              endcase
            end
          MD_LAST : 
            begin
              unique case (operator_iA)
                MD_OP_MULL : 
                  begin
                    accum_window_dA = res_adder_lA;
                    md_state_dA = MD_IDLE;
                    multdiv_holdA = ~multdiv_ready_id_iA;
                  end
                MD_OP_MULH : 
                  begin
                    accum_window_dA = res_adder_lA;
                    md_state_dA = MD_IDLE;
                    md_state_dA = MD_IDLE;
                    multdiv_holdA = ~multdiv_ready_id_iA;
                  end
                MD_OP_DIV : 
                  begin
                    accum_window_dA = next_quotientA;
                    md_state_dA = MD_CHANGE_SIGN;
                  end
                MD_OP_REM : 
                  begin
                    accum_window_dA = {1'b0, next_remainderA[31:0]};
                    md_state_dA = MD_CHANGE_SIGN;
                  end
                default : ;
              endcase
            end
          MD_CHANGE_SIGN : 
            begin
              md_state_dA = MD_FINISH;
              unique case (operator_iA)
                MD_OP_DIV : accum_window_dA = div_change_signA ? {1'b0, alu_adder_iA} : accum_window_qA;
                MD_OP_REM : accum_window_dA = rem_change_signA ? {1'b0, alu_adder_iA} : accum_window_qA;
                default : ;
              endcase
            end
          MD_FINISH : 
            begin
              md_state_dA = MD_IDLE;
              multdiv_holdA = ~multdiv_ready_id_iA;
            end
          default : 
            begin
              md_state_dA = MD_IDLE;
            end
        endcase
      end

  end

