                  end
                MD_OP_DIV, MD_OP_REM : 
                  begin
                    accum_window_dB = {next_remainderB[31:0], op_numerator_qB[multdiv_count_dB]};
                    op_a_shift_dB = next_quotientB;
                    md_state_dB = (multdiv_count_qVotedB==5'd1) ? MD_LAST : MD_COMP;
                  end
                default : ;
              endcase
            end
          MD_LAST : 
            begin
              unique case (operator_iB)
                MD_OP_MULL : 
                  begin
                    accum_window_dB = res_adder_lB;
