            end
          MD_CHANGE_SIGN : 
            begin
              md_state_dB = MD_FINISH;
              unique case (operator_iB)
                MD_OP_DIV : accum_window_dB = div_change_signB ? {1'b0, alu_adder_iB} : accum_window_qB;
                MD_OP_REM : accum_window_dB = rem_change_signB ? {1'b0, alu_adder_iB} : accum_window_qB;
