assign multdiv_enC =  (mult_en_iC|div_en_iC) &~multdiv_holdC;

always_ff @( posedge clk_iA or negedge rst_niA )
  begin
    if (!rst_niA)
      begin
        multdiv_count_qA <= 5'h0;
        op_b_shift_qA <= 33'h0;
        op_a_shift_qA <= 33'h0;
        md_state_qA <= MD_IDLE;
        div_by_zero_qA <= 1'b0;
      end
    else
      if (multdiv_enA)
        begin
          multdiv_count_qA <= multdiv_count_dA;
          op_b_shift_qA <= op_b_shift_dA;
          op_a_shift_qA <= op_a_shift_dA;
          md_state_qA <= md_state_dA;
          div_by_zero_qA <= div_by_zero_dA;
        end

  end

